public class Solution {
    // SPEC: remove every failing score (< 60), keep order, return how many removed
    public static int removeFailing(java.util.ArrayList<Integer> scores) {
        int removed = 0;
        for (int i = 0; i < scores.size(); i++) {
            if (scores.get(i) < 60) {
                scores.remove(i);
                removed++;
            }
        }
        return removed;
    }
}

